<include file="Public:header"/><style type="text/css">    .table-list th{        width: 8%;    }</style><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Qiye/lists')}" class="on">企业列表</a>|					<a href="javascript:void(0);" onclick="add_qiye()">添加企业</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td style="width:60%;">						<form action="{pigcms{:U('Qiye/lists')}" method="get">                            <input type="hidden" name="c" value="Qiye"/>                            <input type="hidden" name="a" value="lists"/>							筛选:							<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" area_id="{pigcms{$_GET.area_id}" style="display:inline"></div>							<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="name" <if condition="$_GET['searchtype'] eq 'name'">selected="selected"</if>>企业名称</option>								<option value="id" <if condition="$_GET['searchtype'] eq 'id'">selected="selected"</if>>企业ID</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							企业状态: <select name="searchstatus">								<option value="1" <if condition="$_GET['searchstatus'] eq 1">selected="selected"</if>>启用</option>								<option value="0" <if condition="$_GET['searchstatus'] eq '0'">selected="selected"</if>>关闭</option>							</select>							<!--排序: <select name="searchorder">								<option value="0" <if condition="$_GET['searchorder'] eq 0">selected="selected"</if>>注册时间</option>								<option value="1" <if condition="$_GET['searchorder'] eq '1'">selected="selected"</if>>未结算金额</option>                                <option value="1" <if condition="$_GET['searchorder'] eq '1'">selected="selected"</if>>未消费余额</option>							</select>-->                            <if condition="$config['merchant_type_switch'] eq 1 && $type_list">                                商家类型：                                <select name="merchant_type">                                    <option value="0">全部类型</option>                                    <volist name="type_list" id="vo">                                        <option value="{pigcms{$vo['type_id']}" <if condition="$_GET['merchant_type'] eq $vo['type_id']">selected="selected"</if>>{pigcms{$vo['type_name']}</option>                                    </volist>                                </select>                            </if>							<input type="submit" value="查询" class="button"/>													</form>					</td>					<notempty name="export">					<td>						<a  href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出列表</a>					</td>					</notempty>				</tr>			</table>							<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>                                <th style="width: 5%">ID</th>                                <th style="width: 5%">企业ID</th>								<th>企业账号</th>                                <th>企业名称</th>                                <th>联系电话</th>                                <th>结算手续费比例</th>                                <th>结算方式</th>                                <th>未结算金额</th>                                <th style="width: 5%">员工关联数</th>                                <th style="width: 5%">商家关联数</th>                                <th style="width: 5%">状态</th>                                <th>访问企业后台</th>                                <th>消费数据报表</th>                                <th>操作</th>						</thead>						<tbody>                        <notempty name="qiyes">                            <volist name="qiyes" id="q">                                <tr>                                    <td>{pigcms{$q.qiye_id}</td>                                    <td>{pigcms{$q.account_id}</td>                                    <td>{pigcms{$q.account}</td>                                    <td>{pigcms{$q.name}</td>                                    <td>{pigcms{$q.phone}</td>                                    <td>{pigcms{$q.settlement_ratio}</td>                                    <td><if condition="$q['settlement_type'] eq 1"><font color="green">先消费后结算</font><else/><font color="red">先结算后消费</font></if></td>                                    <td>{pigcms{$q.money|floatval}</td>                                    <td><a href="{pigcms{:U('Qiye/staff',array('qiye_id'=>$q['qiye_id']))}">{pigcms{$q.staff_num}</a></td>                                    <td><a href="{pigcms{:U('Qiye/merchant',array('qiye_id'=>$q['qiye_id']))}">{pigcms{$q.merchant_num}</a></td>                                    <td><if condition="$q['status'] eq 1"><font color="green">启用</font><else/><font color="red">关闭</font></if></td>                                    <td><a target="_blank" href="{pigcms{:U('Qiye/login',array('qiye_id'=>$q['qiye_id']))}">访问</a></td>                                    <td><a href="{pigcms{:U('Qiye/trade',array('qiye_id'=>$q['qiye_id']))}">消费数据报表</a></td>                                    <td><a href="javascript:void(0);" onclick="qiye_edit({pigcms{$q.qiye_id})">编辑</a></td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="15">{pigcms{$pagebar}</td></tr>                        <else/>                            <tr><td class="textcenter red" colspan="15">列表为空！</td></tr>                        </notempty>						</tbody>					</table>				</div>				</div><script>  function add_qiye(){      window.top.artiframe('{pigcms{:U('Qiye/add')}','添加企业',800,500,true,false,false,addbtn,'add',true);  }  function qiye_edit(id){      window.top.artiframe('{pigcms{:U('Qiye/edit')}'+'&qiye_id='+id,'编辑企业',800,500,true,false,false,addbtn,'add',true);  }</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>